import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:yaqeen/features/prayer/domain/prayer_calculator.dart';
import 'package:yaqeen/features/prayer/domain/qibla.dart';

/// Golden tables generated by tools/prayer/golden.mjs from the adhan JS library (which the
/// Dart engine ports). Spec §6.4: ±1 minute for Cairo, Alexandria, Aswan, Makkah, London.
void main() {
  final golden = (jsonDecode(File('test/fixtures/prayer_golden.json').readAsStringSync()) as List).cast<Map<String, dynamic>>();
  const calc = AstronomicalPrayerCalculator();

  test('matches the reference within one minute for every place, method and season', () {
    var compared = 0;
    for (final g in golden) {
      final d = DateTime.parse(g['date'] as String);
      final t = calc.compute(
        year: d.year,
        month: d.month,
        day: d.day,
        latitude: (g['lat'] as num).toDouble(),
        longitude: (g['lng'] as num).toDouble(),
        params: PrayerParams(method: CalcMethod.fromWire(g['method'] as String), asr: AsrSchool.fromWire(g['asr'] as String)),
      );
      for (final (name, actual) in [
        ('fajr', t.fajr),
        ('sunrise', t.sunrise),
        ('dhuhr', t.dhuhr),
        ('asrTime', t.asr),
        ('maghrib', t.maghrib),
        ('isha', t.isha),
      ]) {
        final expected = DateTime.parse(g[name] as String);
        final diff = actual.difference(expected).inSeconds.abs();
        expect(diff, lessThanOrEqualTo(60), reason: '${g['place']} ${g['date']} ${g['asr']} $name: $actual vs $expected');
        compared++;
      }
    }
    expect(compared, golden.length * 6);
  });

  // Regression lock (engine output, = adhan reference). Spec acceptance also asks for a check
  // against the Egyptian General Authority's published table — do that on device before release.
  test('Cairo on 20 Oct 2026 (Egyptian, standard Asr) — exact local times', () {
    final t = calc.compute(year: 2026, month: 10, day: 20, latitude: 30.0444, longitude: 31.2357, params: const PrayerParams());
    // Egypt is UTC+3 on this date (summer time until 29 Oct 2026).
    String hm(DateTime utc) {
      final l = utc.add(const Duration(hours: 3));
      return '${l.hour}:${l.minute.toString().padLeft(2, '0')}';
    }

    expect([hm(t.fajr), hm(t.dhuhr), hm(t.asr), hm(t.maghrib), hm(t.isha)], ['5:33', '12:41', '15:53', '18:19', '19:37']);
  });

  test('Umm al-Qura adds 30 minutes to Isha in Ramadan', () {
    final normal = calc.compute(year: 2027, month: 2, day: 20, latitude: 21.4225, longitude: 39.8262, params: const PrayerParams(method: CalcMethod.ummAlQura));
    final ramadan = calc.compute(year: 2027, month: 2, day: 20, latitude: 21.4225, longitude: 39.8262, params: const PrayerParams(method: CalcMethod.ummAlQura, ramadan: true));
    expect(ramadan.isha.difference(normal.isha).inMinutes, 30);
    expect(normal.isha.difference(normal.maghrib).inMinutes, 90);
  });

  test('per-prayer adjustments shift only that prayer', () {
    const base = PrayerParams();
    final a = calc.compute(year: 2026, month: 10, day: 20, latitude: 30.0444, longitude: 31.2357, params: base);
    final b = calc.compute(
      year: 2026,
      month: 10,
      day: 20,
      latitude: 30.0444,
      longitude: 31.2357,
      params: const PrayerParams(adjustments: PrayerAdjustments(isha: 2)),
    );
    expect(b.isha.difference(a.isha).inMinutes, 2);
    expect(b.fajr, a.fajr);
  });

  test('recommended method by country', () {
    expect(CalcMethod.recommendedFor('EG'), CalcMethod.egypt);
    expect(CalcMethod.recommendedFor('SA'), CalcMethod.ummAlQura);
    expect(CalcMethod.recommendedFor('GB'), CalcMethod.mwl);
  });

  group('qibla', () {
    test('Cairo is 136° ±1 (spec §5.16) and about 1,280 km away', () {
      expect(qiblaBearing(30.0444, 31.2357), closeTo(136, 1));
      expect(distanceToKaabaKm(30.0444, 31.2357), closeTo(1280, 15));
    });

    test('guidance turns the short way and aligns within 3°', () {
      expect(turnToQibla(130, 136), closeTo(6, 1e-9));
      expect(guidanceFor(turnToQibla(130, 136)), QiblaGuidance.turnRight);
      expect(guidanceFor(turnToQibla(200, 136)), QiblaGuidance.turnLeft);
      expect(turnToQibla(350, 136), closeTo(146, 1e-9)); // right is shorter than 214° left
      expect(guidanceFor(turnToQibla(134, 136)), QiblaGuidance.aligned);
      expect(compassPoint(136), CompassPoint.se);
    });
  });
}
